from pathlib import Path
p=Path('/mnt/data/phase011/apps/public-web/lib/appliance-catalogue.ts')
s=p.read_text()
marker='\n];\nexport const homeApplianceProducts'
assert marker in s

def entry(slug,brand,name,domain,cat,family,desc=None,specs=None):
    import json
    desc=desc or f"{name} for everyday use at home."
    specs=specs or {"Type":family}
    qs=list(specs.values())[:3] or [family]
    def q(x): return json.dumps(x, ensure_ascii=False)
    return " p({slug:%s,brand:%s,name:%s,domain:%s,category:%s,family:%s,shortDescription:%s,description:%s,quickSpecs:%s,specs:%s})," % tuple(q(x) for x in [slug,brand,name,domain,cat,family,desc,desc,qs,specs])

P=[]
def add(*a,**kw): P.append(entry(*a,**kw))
