# dedupe generated slugs and avoid collision with existing
existing=set()
import re
for m in re.finditer(r"slug:'([^']+)'",s): existing.add(m.group(1))
out=[]
for x in P:
    m=re.search(r"slug:(?:'|\")([^'\"]+)(?:'|\")",x); slug=m.group(1)
    if slug in existing: continue
    existing.add(slug); out.append(x)
s=s.replace(marker,'\n'+ '\n'.join(out) + marker)
p.write_text(s)
print('added',len(out),'entries; total slug count',len(existing))
